import{H as e,_t as t,nt as n,rt as r}from"./chunks/framework.ByJSXnli.js";var i=JSON.parse(`{"title":"Developer guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/developer-guidelines.md","filePath":"contributing/developer-guidelines.md"}`),a={name:`contributing/developer-guidelines.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="developer-guidelines" tabindex="-1">Developer guidelines <a class="header-anchor" href="#developer-guidelines" aria-label="Permalink to “Developer guidelines”">​</a></h1><p>This is the canonical implementation and architecture guide for HeuristicLib contributors. It turns the <a href="/contributing/design-goals.html">design goals</a> into rules for code, public APIs and repository changes.</p><p>Use the <a href="/reference/glossary.html">Glossary</a> for terminology and <code>AGENTS.md</code> for repository workflow. Topic documentation owns public contracts and examples.</p><p>Cite a section as <code>§ 4</code> and a rule as <code>§ 4.2</code>. Rule numbers are stable. Add rules at the end of their section and do not reuse removed numbers.</p><h2 id="documentation-roles" tabindex="-1">Documentation roles <a class="header-anchor" href="#documentation-roles" aria-label="Permalink to “Documentation roles”">​</a></h2><p>Each steering document has one responsibility:</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Document</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/contributing/requirements.html">Requirements</a></td><td>What the library must support and which capability boundaries matter</td></tr><tr><td><a href="/contributing/design-goals.html">Design goals and principles</a></td><td>Which durable qualities the resulting library should have</td></tr><tr><td><a href="/contributing/developer-guidelines.html">Developer guidelines</a></td><td>How contributors implement those requirements and goals</td></tr><tr><td><a href="/reference/glossary.html">Glossary</a></td><td>Which terminology is canonical</td></tr><tr><td>GitHub Issues</td><td>Concrete problems, feature requests and design repairs, with the decisions belonging to that work</td></tr><tr><td><code>AGENTS.md</code></td><td>How contributors navigate and validate the repository and which design changes agents discuss first</td></tr></tbody></table></div><p>Topic pages must not become alternative policy documents.</p><p>User-facing documentation describes current behavior and contracts. Describe how the library works without announcing that it &quot;now&quot; works that way.</p><h2 id="§-1-project-posture" tabindex="-1">§ 1 Project posture <a class="header-anchor" href="#§-1-project-posture" aria-label="Permalink to “§ 1 Project posture”">​</a></h2><h3 id="§-1-1-treat-alpha-apis-as-provisional" tabindex="-1">§ 1.1 Treat alpha APIs as provisional <a class="header-anchor" href="#§-1-1-treat-alpha-apis-as-provisional" aria-label="Permalink to “§ 1.1 Treat alpha APIs as provisional”">​</a></h3><ul><li>Backward compatibility is not currently a design goal.</li><li>Existing code and APIs are evidence, not permanent commitments.</li><li>Replace a weak API when a materially stronger design is available instead of adding compatibility around the weak design.</li><li>Every change must solve a concrete problem. Alpha status does not justify arbitrary churn.</li><li>Current folders, assemblies, namespaces and packages are provisional. Do not treat them as the final architecture.</li></ul><h2 id="§-2-making-design-changes" tabindex="-1">§ 2 Making design changes <a class="header-anchor" href="#§-2-making-design-changes" aria-label="Permalink to “§ 2 Making design changes”">​</a></h2><h3 id="§-2-1-start-with-the-user-problem" tabindex="-1">§ 2.1 Start with the user problem <a class="header-anchor" href="#§-2-1-start-with-the-user-problem" aria-label="Permalink to “§ 2.1 Start with the user problem”">​</a></h3><ol><li>State the concrete problem.</li><li>Compare meaningful alternatives, including the smallest change within the existing design and the simplest coherent design if it differs.</li><li>Show the chosen tradeoffs through representative usage.</li><li>State the concepts each alternative adds and removes.</li><li>Prefer designs that make intended usage obvious and misuse difficult.</li><li>Update implementation, tests, API usage specs and documentation together.</li></ol><h3 id="§-2-2-establish-important-user-flows-with-executable-specs" tabindex="-1">§ 2.2 Establish important user flows with executable specs <a class="header-anchor" href="#§-2-2-establish-important-user-flows-with-executable-specs" aria-label="Permalink to “§ 2.2 Establish important user flows with executable specs”">​</a></h3><p>Use executable API usage specs for important user flows. Keep them small and representative.</p><h3 id="§-2-3-require-every-pattern-to-have-a-concrete-responsibility" tabindex="-1">§ 2.3 Require every pattern to have a concrete responsibility <a class="header-anchor" href="#§-2-3-require-every-pattern-to-have-a-concrete-responsibility" aria-label="Permalink to “§ 2.3 Require every pattern to have a concrete responsibility”">​</a></h3><p>Every pattern needs a concrete responsibility. This includes streaming, explicit runs, configuration and execution separation, builders and helper base classes.</p><h3 id="§-2-4-review-changes-for-overall-code-health" tabindex="-1">§ 2.4 Review changes for overall code health <a class="header-anchor" href="#§-2-4-review-changes-for-overall-code-health" aria-label="Permalink to “§ 2.4 Review changes for overall code health”">​</a></h3><p>Evaluate requirements and correctness, readability, architecture, relevant security risks and performance. A change should improve overall code health without requiring perfection or unrelated cleanup.</p><ul><li>Check findings against the actual callers, contracts and tests. Cite the affected code, the relevant requirement or principle and the practical consequence.</li><li>For a structural concern, describe a simpler alternative and its tradeoffs. Consider deletion, inlining and consolidation as well as extraction. Explain whether complexity disappears or merely moves.</li><li>Judge simplicity by the concepts, ownership rules and coordination a reader or extension author must understand. Line counts, file sizes and repeated syntax are inspection signals, not automatic reasons to split or generalize.</li><li>Distinguish required fixes from optional suggestions, and problems introduced by the change from pre-existing concerns. Do not invent findings. No material concern is a valid conclusion.</li><li>Justify useful abstractions as well as questioning unnecessary ones. A pattern name or a SOLID label alone is not evidence that a design is better.</li></ul><h3 id="§-2-5-express-new-scenarios-with-existing-mechanisms" tabindex="-1">§ 2.5 Express new scenarios with existing mechanisms <a class="header-anchor" href="#§-2-5-express-new-scenarios-with-existing-mechanisms" aria-label="Permalink to “§ 2.5 Express new scenarios with existing mechanisms”">​</a></h3><p>Write a new scenario with the existing configuration nodes and rules before proposing a mechanism. Propose one only when the scenario cannot reasonably be expressed that way, and state which existing mechanism it makes redundant. A concept that users must learn needs that justification too, and removing a concept is the better outcome (§ 2.1, § 3.1).</p><ul><li>Add behavior through configuration nodes. A convenience produces nodes and does not behave differently from them. Do not add a new way to change an executor after construction.</li><li>Let the executor graph follow from the configuration graph and the problem. Do not add a dependency on anything else, such as attachment order, request context or global registration, without a recorded decision.</li><li>Treat a new guard or ordering rule as a sign of temporal coupling. Try to remove the coupling before adding the check. Validating configured values remains the responsibility § 4.7 describes.</li></ul><h2 id="§-3-architecture-and-responsibility-boundaries" tabindex="-1">§ 3 Architecture and responsibility boundaries <a class="header-anchor" href="#§-3-architecture-and-responsibility-boundaries" aria-label="Permalink to “§ 3 Architecture and responsibility boundaries”">​</a></h2><h3 id="§-3-1-keep-responsibilities-explicit-and-concepts-coherent" tabindex="-1">§ 3.1 Keep responsibilities explicit and concepts coherent <a class="header-anchor" href="#§-3-1-keep-responsibilities-explicit-and-concepts-coherent" aria-label="Permalink to “§ 3.1 Keep responsibilities explicit and concepts coherent”">​</a></h3><ul><li>Keep responsibility boundaries clear.</li><li>Prefer a small number of coherent concepts over parallel abstractions with overlapping semantics.</li><li>Keep abstractions small and explicit.</li><li>Prefer strong static typing, explicit invariants and compile time safety to conventions or late runtime checks.</li><li>Make invalid states unrepresentable where practical.</li><li>Keep dependencies such as randomness, cancellation, time, scheduling, caches and execution context explicit.</li><li>Avoid ambient state, unnecessary runtime machinery, global registries and opaque indirection.</li><li>Describe architecture through responsibilities, not source layout.</li><li>Optimize public APIs for human users first with clear naming, predictable contracts and visible costs.</li></ul><h3 id="§-3-2-keep-the-conceptual-core-independent-of-authoring-conveniences" tabindex="-1">§ 3.2 Keep the conceptual core independent of authoring conveniences <a class="header-anchor" href="#§-3-2-keep-the-conceptual-core-independent-of-authoring-conveniences" aria-label="Permalink to “§ 3.2 Keep the conceptual core independent of authoring conveniences”">​</a></h3><p>Builders, factories, extensions and helper bases may support the conceptual core. They must not define it.</p><h3 id="§-3-3-treat-consumer-provided-types-as-first-class" tabindex="-1">§ 3.3 Treat consumer-provided types as first class <a class="header-anchor" href="#§-3-3-treat-consumer-provided-types-as-first-class" aria-label="Permalink to “§ 3.3 Treat consumer-provided types as first class”">​</a></h3><p>An operator, operator role, algorithm, encoding, search space, problem or invariant declared in a consumer&#39;s assembly participates on the same terms as one shipped in the package. Shipping first is not a privilege, and there is no tier of built-in types that mechanisms serve better.</p><p>The failure mode is a mechanism that <strong>enumerates</strong> the built-in cases: a base class implementing the built-in roles&#39; interfaces, a switch over the known encodings, a registry seeded with the package&#39;s own types. Each works for what it lists and silently demotes everything else into a second tier a consumer cannot join without editing the library. Reach a type through what that type declares about itself, not through a list of types the library happens to know.</p><p>The following settled decisions rest on this rule.</p><ul><li>Invariant checking keys on whether a contract is declared, never on which role an operator fills. A role added by a consumer participates unchanged, and a role whose output is not a candidate simply never declares one.</li><li>Operator recommendation resolution keys on <code>IRecommends&lt;TOperator&gt;</code>, never on a list of known roles. A consumer defined role participates by using its own role contract as <code>TOperator</code>.</li><li><code>TryCreateRecommendedOperator</code> returns <code>true</code> with a fresh, nonnull operator when the source recommends one in its current state. It returns <code>false</code> with <code>null</code> to decline, which lets resolution continue to the next source.</li><li><code>Problem&lt;TSelf, TCandidate, TSearchSpace&gt;</code> does not implement recommendation interfaces for built-in roles. A base class naming them would supply those roles permanently while a consumer&#39;s role still required separate treatment. Problems and search spaces implement only the recommendations they make. See <a href="/guide/fundamentals/algorithms.html#use-operator-recommendations">Algorithms</a>.</li></ul><p>Built-in components follow the same rule from the other side. A built-in operator, wrapper, analyzer or clock uses only members that an external author can use the same way, which is why <code>OperationInfo.For</code>, <code>RunResults.TimeProvider</code>, <code>BestSoFarAnalyzer.Evaluations</code> and <code>RankAnalyzer.Genealogy</code> are public. An automatic path has no capability the explicit one lacks: whatever <code>CreateRun</code> or <code>Substitute</code> places for an analyzer, a caller can place by hand with the same result. When a built-in component needs an internal member, make that member public or change the design.</p><h3 id="§-3-4-separate-membership-invariants-and-recommendations" tabindex="-1">§ 3.4 Separate membership, invariants and recommendations <a class="header-anchor" href="#§-3-4-separate-membership-invariants-and-recommendations" aria-label="Permalink to “§ 3.4 Separate membership, invariants and recommendations”">​</a></h3><p>A search space describes which candidates belong to it and which invariants all its members satisfy. Split search space types when membership or data exposed to operators differ. Do not split a search space only to make different operators appear suitable for different problems over the same candidates.</p><p>Use operator contracts to state whether an operator accepts the search space&#39;s members and keeps its outputs inside the space. Use problem and search space recommendations to suggest suitable starting operators. A recommendation is not a compatibility restriction and an operator omitted from the recommendations remains a valid experiment.</p><p><code>IsSubspaceOf</code> describes candidate membership only. Do not use it as a substitute for operator contracts or recommendations.</p><h3 id="§-3-5-keep-dependencies-within-their-layers" tabindex="-1">§ 3.5 Keep dependencies within their layers <a class="header-anchor" href="#§-3-5-keep-dependencies-within-their-layers" aria-label="Permalink to “§ 3.5 Keep dependencies within their layers”">​</a></h3><p>Follow the <a href="/contributing/architecture/layering.html">layering rules</a> when adding or moving types. Assign a type by its responsibility, including where a namespace contains both contracts and implementations, and keep dependencies directed from higher layers to lower ones. Treat configuration and executor as phases within those responsibilities.</p><h3 id="§-3-6-apply-clean-code-values-with-judgment" tabindex="-1">§ 3.6 Apply clean code values with judgment <a class="header-anchor" href="#§-3-6-apply-clean-code-values-with-judgment" aria-label="Permalink to “§ 3.6 Apply clean code values with judgment”">​</a></h3><p>Use these values when designing, implementing and reviewing code. Each must explain a concrete responsibility, invariant or cost in HeuristicLib. They do not authorize changes to accepted contracts or require a particular number of classes, interfaces or patterns.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Value</th><th>Application in HeuristicLib</th></tr></thead><tbody><tr><td>KISS and YAGNI</td><td>Prefer the simplest coherent design that meets the requirements. Add abstractions and extension points for demonstrated needs or required capability boundaries. Explain what knowledge or coordination they remove.</td></tr><tr><td>DRY</td><td>Give each semantic rule one owner. Similar syntax alone does not justify combining behavior that changes for different reasons.</td></tr><tr><td>Single responsibility and cohesion</td><td>Keep behavior that changes for the same reasons together. Separate independent policies and state lifetimes without fragmenting cohesive behavior into trivial types.</td></tr><tr><td>Separation of concerns and abstraction levels</td><td>Keep composition and resolution distinct from operation behavior. Make orchestration readable without forcing every small operation into another helper.</td></tr><tr><td>Composition and substitution</td><td>Prefer composition for independently varying behavior. Use inheritance when subtypes preserve the behavioral contract, including preconditions, results, ownership, ordering and failure semantics.</td></tr><tr><td>Dependency inversion</td><td>Keep dependencies explicit and directed according to § 3.5. Introduce an interface when it provides a meaningful policy or substitution boundary, rather than one interface per class.</td></tr><tr><td>Interface segregation</td><td>Require only capabilities a client needs. An external operation should not implement unrelated candidate or problem contracts.</td></tr><tr><td>Open/closed and external extensibility</td><td>Extend through declared contracts, with consumer-provided types participating as § 3.3 requires. Do not enumerate built-in cases in shared mechanisms. This does not prevent deliberate alpha API changes under § 1.1.</td></tr><tr><td>Information hiding and least astonishment</td><td>Expose necessary capabilities and predictable costs, defaults and side effects. Keep construction details and private execution state behind the responsible boundary.</td></tr><tr><td>Tell, don&#39;t ask and the Law of Demeter</td><td>Put invariant-preserving behavior with its owner and avoid callers navigating another object&#39;s internals. Value-oriented candidate and search-state data remains appropriate. Do not add forwarding layers merely to shorten access chains.</td></tr><tr><td>Component orientation and implementation reflects design</td><td>Give components coherent contracts and explicit dependencies. Organize code by the existing responsibility layers. A framework pattern or folder layout is not a design goal by itself.</td></tr></tbody></table></div><h3 id="§-3-7-introspect-through-declarations-not-reflection" tabindex="-1">§ 3.7 Introspect through declarations, not reflection <a class="header-anchor" href="#§-3-7-introspect-through-declarations-not-reflection" aria-label="Permalink to “§ 3.7 Introspect through declarations, not reflection”">​</a></h3><p>Avoid reflection in library logic and tests. A walk over a configuration graph reads the declared parameters through <code>GetParameters</code>, and a question about a configuration is a member it answers, such as <code>Supports</code>. The declared parameter walk is not reflection. Comparing types with <code>typeof</code> and <code>IsAssignableTo</code> is ordinary type checking. Reflection that only words an exception message is acceptable. Architecture and arity tests read source through the Roslyn compilation the architecture tests build, and reading assembly references from metadata remains acceptable. A check that must see undeclared members belongs in a Roslyn analyzer, because only source shows what a declaration omits.</p><h2 id="§-4-configuration-and-execution-ownership" tabindex="-1">§ 4 Configuration and execution ownership <a class="header-anchor" href="#§-4-configuration-and-execution-ownership" aria-label="Permalink to “§ 4 Configuration and execution ownership”">​</a></h2><p>See <a href="/contributing/architecture/execution-resolution.html">execution resolution</a> for executor construction, state sharing and contextual node binding.</p><h3 id="§-4-1-separate-reusable-configurations-from-executors" tabindex="-1">§ 4.1 Separate reusable configurations from executors <a class="header-anchor" href="#§-4-1-separate-reusable-configurations-from-executors" aria-label="Permalink to “§ 4.1 Separate reusable configurations from executors”">​</a></h3><p>Configurations own immutable settings, child configurations and analyzers. Executors own private mutable data. Share an executor explicitly with <code>Sharing</code>. Analyzer results belong to one run. Invocation-local values stay in the operation or iterator. Never store mutable execution data on a configuration.</p><h3 id="§-4-2-keep-execution-data-out-of-search-states" tabindex="-1">§ 4.2 Keep execution data out of search states <a class="header-anchor" href="#§-4-2-keep-execution-data-out-of-search-states" aria-label="Permalink to “§ 4.2 Keep execution data out of search states”">​</a></h3><p>Search states are public progress values. Do not use them to carry private counters, caches or other execution data.</p><h3 id="§-4-3-resolve-declared-children-through-the-resolution-scope" tabindex="-1">§ 4.3 Resolve declared children through the resolution scope <a class="header-anchor" href="#§-4-3-resolve-declared-children-through-the-resolution-scope" aria-label="Permalink to “§ 4.3 Resolve declared children through the resolution scope”">​</a></h3><p>Every configuration&#39;s construction hook receives a resolution scope: <code>CreateExecutor</code> is typed to the run for operators and algorithms, while <code>CreateExecutionNode</code> builds other execution nodes. Resolve children through it and pass them to the executor. Retain a scope only for delayed child construction. To keep one executor for a configuration across several uses, share it with <code>Sharing</code> on the node whose lifetime it should follow rather than caching executors yourself. Do not add another scope abstraction or call a child&#39;s hook directly.</p><p>Algorithms resolve only their configured parameters and create no operators of their own. Keep those parameters as supplied. Behavior derived from a parameter, such as a mutation rate, belongs in the algorithm&#39;s execution code. Independent operators doing real work must be parameters so observations and budgets can see them.</p><p>A configuration an algorithm builds itself is not a declared child, so substitutions do not reach it, and analysis or budgets placed by the user miss its work. This is an authoring guideline, not a rule enforced by the resolver. A wrapper holds the configuration it wraps as a declared child. Supply concrete runtime dependencies through the wrapper&#39;s properties and pass them to its executor. Keep run-result lookup and child resolution in configuration hooks.</p><p>Constructing a node never changes the rules for its siblings. A <code>CreateExecutor</code> hook resolves its children and builds its executor. It does not change how the scope builds any other configuration. Behavior around a configuration is a wrapper in the configuration graph, so it affects only the configuration it holds and is visible before resolution begins. The one scope change during construction is <code>Share</code>, which changes only how long an executor lives and fails for a configuration that the scope or a scope below it has already resolved.</p><h3 id="§-4-4-expose-one-construction-hook" tabindex="-1">§ 4.4 Expose one construction hook <a class="header-anchor" href="#§-4-4-expose-one-construction-hook" aria-label="Permalink to “§ 4.4 Expose one construction hook”">​</a></h3><p>Every configuration exposes one construction hook, which resolution calls for every build. Operation-parameterized operators expose <code>CreateExecutor&lt;TSearchSpace, TProblem, TSearchState&gt;(scope)</code>, which builds an executor for the operation and run types. Algorithms expose <code>CreateExecutor&lt;TSearchSpace, TProblem&gt;(scope)</code> with a scope typed to the run and their search state. A consumer-defined role implements <code>IConfigurationNode&lt;TExecutionNode&gt;.CreateExecutionNode(ResolutionScope)</code>. Private data belongs to executor fields. Use <code>Sharing</code> to share executors and <code>scope.Results.Result(configuration)</code> to read run results. Do not add a second initializer per operation, role-named alternatives or a competing public entry.</p><p>Operator authoring bases own the public entry. Fixed-signature leaves override protected <code>CreateExecutor</code> with a scope typed to their candidate, search space, problem and search state. Generic compositions override the protected run-generic <code>CreateExecutor</code> and resolve current children through its typed scope. Transparent generic wrappers return <code>scope.ResolveOperator(ChildOperator)</code> or wrap that resolved child with <code>TOperation.Wrap&lt;TCandidate, TSearchState, TWrapper&gt;(childOperator, wrapper)</code>. Their canonical configuration properties are <code>ChildOperator</code> and <code>ChildOperators</code>.</p><p>A hook resolves each child into a local variable named after its property, in the order the children must be built, and then passes the variables to the executor constructor. Only a hook that does nothing but return one resolved child returns the resolution directly.</p><p>Algorithm authoring bases own the public entry and expose one protected <code>CreateExecutor</code>: run-generic for agnostic algorithms, typed to the declared search space and problem for bound ones. A wrapping algorithm resolves its <code>ChildAlgorithm</code> through the scope and builds its executor around the result, using the same executor interface for the child and result.</p><h3 id="§-4-5-keep-construction-entry-points-semantically-equivalent" tabindex="-1">§ 4.5 Keep construction entry points semantically equivalent <a class="header-anchor" href="#§-4-5-keep-construction-entry-points-semantically-equivalent" aria-label="Permalink to “§ 4.5 Keep construction entry points semantically equivalent”">​</a></h3><p>Keep public constructors as the direct path. Add <code>Create</code> for generic inference and a fluent extension when its receiver becomes a child configuration. All paths construct the same configuration.</p><h3 id="§-4-6-give-each-configuration-setting-one-input-path" tabindex="-1">§ 4.6 Give each configuration setting one input path <a class="header-anchor" href="#§-4-6-give-each-configuration-setting-one-input-path" aria-label="Permalink to “§ 4.6 Give each configuration setting one input path”">​</a></h3><p>A setting has one input path.</p><ul><li>Required values are constructor parameters without defaults.</li><li>Optional values are <code>init</code> properties with defaults. Do not also put them in the constructor.</li><li>Every configuration property is <code>{ get; init; }</code> so <code>with</code> can vary it.</li><li>Executor children and run data are <code>{ get; }</code> because executors are not reconfigured.</li></ul><h3 id="§-4-7-validate-complete-configurations-when-building" tabindex="-1">§ 4.7 Validate complete configurations when building <a class="header-anchor" href="#§-4-7-validate-complete-configurations-when-building" aria-label="Permalink to “§ 4.7 Validate complete configurations when building”">​</a></h3><p>Retain configuration values unchanged during construction and <code>with</code>. Validate them at the start of <code>CreateExecutor</code> and throw <code>InvalidOperationException</code> before execution begins. Bound bases validate run-type compatibility before calling the hook. Do not add a separate validation API.</p><p>For operation parameterized operators, validate immutable configuration at the start of <code>CreateExecutor</code> before resolving children. <code>Supports</code> supplies preflight metadata and resolution checks each executor against its requested interface. A wrapper rejects a child it cannot serve in its constructor, or in <code>CreateExecutor</code> before it resolves the child. A construction failure ends the scope tree while retaining published results.</p><p>Analyzer result creation must not depend on a requesting executor or its children. Its <code>CreateExecutionNode</code> receives a root <code>ResolutionScope</code>. Recorders receive only <code>RunResults</code>. Clock readings are run results created by clocks in the root scope and obtained through <code>results.Result(clock)</code>. Failed creation publishes no result. A later lookup can retry. A failure during executor construction ends the scope tree, while published results remain readable.</p><h3 id="§-4-8-represent-configured-behavior-with-value-strategies" tabindex="-1">§ 4.8 Represent configured behavior with value strategies <a class="header-anchor" href="#§-4-8-represent-configured-behavior-with-value-strategies" aria-label="Permalink to “§ 4.8 Represent configured behavior with value strategies”">​</a></h3><p>Configurations are data: by convention they compare by value and can be serialized. Represent configured behavior with a strategy interface whose implementations are immutable values.</p><p>A configuration may hold a delegate or another live object, such as a host callback. It is not forbidden, but the configuration then leaves the convention: it cannot be serialized, nor can any graph that contains it. Its equality depends on the delegate&#39;s method and target. And captured state is not part of the configuration. Whether that matters is the author&#39;s decision, and many users never serialize a configuration. Document such a type as holding a runtime value, and link the <a href="/guide/fundamentals/configurations.html#configurations-that-hold-delegates">user-facing explanation</a>.</p><p>Library configurations hold runtime values only when there is a technical need, such as Python interoperability, and are listed below. Construction hooks and other machinery that only runs over configurations, and is not stored on them, may use delegates.</p><p>Library configurations that hold runtime values:</p><ul><li>Analyzers and <code>Observing</code> may retain value functions and runtime callbacks, including Python callbacks, and <code>CreateRun</code> or <code>Substitute</code> may place them in a configuration. The source of a role of your own retains the function that places its wrapper, and a trace over it reaches that function.</li><li><code>HeuristicLib.PythonInterop</code> operators such as <code>VisualizationCallbackEvaluator</code> hold Python-facing callbacks.</li><li><code>EpochClock</code> in <code>HeuristicLib.Experimental</code> holds its live dynamic problem, so a configuration holding it is not serializable.</li><li><code>DynamicRacingAlgorithm</code> and <code>DelegatingRacingStateMerger</code> in <code>HeuristicLib.Experimental</code> hold delegates that build, inspect and merge contenders.</li></ul><h3 id="§-4-9-use-records-only-for-value-semantics" tabindex="-1">§ 4.9 Use records only for value semantics <a class="header-anchor" href="#§-4-9-use-records-only-for-value-semantics" aria-label="Permalink to “§ 4.9 Use records only for value semantics”">​</a></h3><p>Use a record only when structural equality is the contract. Use a class for a carrier that holds identity bearing dependencies such as an RNG, executor or registry. Analyzers use reference identity, including when compared as properties of configuration records. Record copies retain those references.</p><h3 id="§-4-10-validate-operation-inputs-before-side-effects" tabindex="-1">§ 4.10 Validate operation inputs before side effects <a class="header-anchor" href="#§-4-10-validate-operation-inputs-before-side-effects" aria-label="Permalink to “§ 4.10 Validate operation inputs before side effects”">​</a></h3><p>Do not add null checks for non-nullable reference parameters or properties. Trust their declared nullability contract.</p><p>Validate problem, search space and operation inputs in the role method before random draws, state changes or substantial work. Configuration checks belong in execution creation.</p><h3 id="§-4-11-expose-configuration-and-hide-execution-machinery" tabindex="-1">§ 4.11 Expose configuration and hide execution machinery <a class="header-anchor" href="#§-4-11-expose-configuration-and-hide-execution-machinery" aria-label="Permalink to “§ 4.11 Expose configuration and hide execution machinery”">​</a></h3><p>Configurations expose their settings and child configurations. Wrapping and multi bases own <code>ChildOperator</code> and <code>ChildOperators</code> or role specific equivalents.</p><p>Executors keep resolved children and machinery private or protected. Use nested operator only for descendants at any depth.</p><h3 id="§-4-12-keep-executor-dependencies-explicit" tabindex="-1">§ 4.12 Keep executor dependencies explicit <a class="header-anchor" href="#§-4-12-keep-executor-dependencies-explicit" aria-label="Permalink to “§ 4.12 Keep executor dependencies explicit”">​</a></h3><p>Use the role&#39;s executor base at every configuration arity, such as the candidate-only <code>MutationExecutor&lt;TCandidate&gt;</code>. Keep the search space, problem and other runtime dependencies the executor reads in its own constructor parameters or fields. The configuration arity determines the contracts available during construction. Executors for wrapping and multi operators also derive from the role&#39;s executor base. Only an executor serving several operations of one configuration implements their interfaces directly, because a class has one base. A concrete executor is a <code>private sealed class Executor</code> nested in its configuration. Only the authoring bases are public executor types. The <code>WrappingOperator</code> and <code>MultiOperator</code> configuration bases have no executor counterparts of their own. Their hooks resolve current children and pass them to the executor.</p><h3 id="§-4-13-give-each-child-slot-one-public-name" tabindex="-1">§ 4.13 Give each child slot one public name <a class="header-anchor" href="#§-4-13-give-each-child-slot-one-public-name" aria-label="Permalink to “§ 4.13 Give each child slot one public name”">​</a></h3><p>A child slot has one public name.</p><ul><li>Use the wrapping or multi base when a child has no role beyond being a child. Do not add an alias for its canonical property.</li><li>Derive from the role base when children have distinct responsibilities. Declare and resolve each child by its role, as <code>SelectorForRemaining</code>, <code>FemaleSelector</code> and <code>MaleSelector</code> do.</li></ul><h3 id="§-4-14-choose-an-operator-base-by-execution-ownership" tabindex="-1">§ 4.14 Choose an operator base by execution ownership <a class="header-anchor" href="#§-4-14-choose-an-operator-base-by-execution-ownership" aria-label="Permalink to “§ 4.14 Choose an operator base by execution ownership”">​</a></h3><p>Choose an authoring base by ownership. See <a href="/contributing/architecture/operator-implementation.html">Operator implementation</a>.</p><ul><li>Use a stateless base for configuration data without mutable run data.</li><li>Author an executor for private mutable fields, child executors or custom execution structure.</li><li>Use a single-candidate base when each item of a batch is processed independently.</li><li>Keep mutable data in executors or run results. Configurations contain no live result or executor.</li><li>Coordinate concurrent access across every executor sharing a resource. An executor local lock cannot protect a shared resource.</li></ul><p>Stateless leaf bases hide executor construction. There is no automatic disposal contract.</p><h3 id="§-4-15-keep-single-candidate-batching-explicit-and-deterministic" tabindex="-1">§ 4.15 Keep single-candidate batching explicit and deterministic <a class="header-anchor" href="#§-4-15-keep-single-candidate-batching-explicit-and-deterministic" aria-label="Permalink to “§ 4.15 Keep single-candidate batching explicit and deterministic”">​</a></h3><p>A single-candidate base seals the batch operation and exposes <code>ExecutionConcurrency Concurrency</code>. Fork each item RNG from its batch position so concurrency does not change results. <code>SingleCandidateMutator</code> is the reference.</p><h3 id="§-4-16-keep-operator-scaffolding-out-of-the-build" tabindex="-1">§ 4.16 Keep operator scaffolding out of the build <a class="header-anchor" href="#§-4-16-keep-operator-scaffolding-out-of-the-build" aria-label="Permalink to “§ 4.16 Keep operator scaffolding out of the build”">​</a></h3><p>Operator scaffolding remains checked in source. Do not add source generators, IDE actions or scaffolding commands for operator families. Coding agents may prepare ordinary source. Review, test and maintain it like handwritten code.</p><h3 id="§-4-17-give-algorithms-explicit-executors" tabindex="-1">§ 4.17 Give algorithms explicit executors <a class="header-anchor" href="#§-4-17-give-algorithms-explicit-executors" aria-label="Permalink to “§ 4.17 Give algorithms explicit executors”">​</a></h3><p>Algorithms use a configuration paired with an explicitly authored executor. Private data belongs to executor fields and shared executors require explicit <code>Sharing</code>. Child operators and interceptors bind per construction. Active iterators retain their children, RNG forks, progress, timers and resources across pause/resume. See <a href="/guide/fundamentals/algorithms.html">Algorithms</a>.</p><p>Iterative algorithms build an <code>IterativeAlgorithmExecutor&lt;TSearchState&gt;</code> in their protected <code>CreateExecutor</code>. Both configuration bases declare that return type, so an iterative algorithm cannot return an executor that skips its interceptor. The bound iterative base derives from the bound <code>Algorithm</code> base and declares its own <code>Interceptor</code>. The hook resolves the optional interceptor and other declared children through its scope and passes them to the executor constructor. Derived algorithm authors own this wiring. The executor base applies the interceptor in its iteration loop. Bound bases check run-type compatibility before calling the hook.</p><h3 id="§-4-18-treat-roslyn-analyzers-as-guardrails" tabindex="-1">§ 4.18 Treat Roslyn analyzers as guardrails <a class="header-anchor" href="#§-4-18-treat-roslyn-analyzers-as-guardrails" aria-label="Permalink to “§ 4.18 Treat Roslyn analyzers as guardrails”">​</a></h3><p>Roslyn analyzers catch recognizable mistakes. They do not prove ownership invariants.</p><h3 id="§-4-19-keep-role-execution-contracts-role-specific" tabindex="-1">§ 4.19 Keep role execution contracts role specific <a class="header-anchor" href="#§-4-19-keep-role-execution-contracts-role-specific" aria-label="Permalink to “§ 4.19 Keep role execution contracts role specific”">​</a></h3><p>Role executors expose their named operation, such as <code>Mutate</code>, <code>Cross</code>, <code>Select</code> or <code>Evaluate</code>. Do not add a generic invocation path, shared problem context carrier or generic bridge between role methods.</p><p>Matching signatures do not satisfy another nominal role. <code>IOperator&lt;TOperation, TCandidate&gt;</code> selects an operation through its <code>IOperation&lt;TSelf&gt;</code>. It does not change executor-interface membership. An operation&#39;s static <code>Wrap</code> connects its named method to <code>IInvocationWrapper</code> during executor construction, and its static <code>IsExecutor</code> lets resolution check an executor without a <code>Type</code>. Each wrapping executor passes a call to its struct wrapper as the operation&#39;s private <code>Invocation</code> struct, an <code>IInvocation&lt;TResult&gt;</code>. Its <code>Random</code> is the call&#39;s random number generator, <code>Proceed(executor, random)</code> calls the named method, optionally on another executor of the same operation, or with another random number generator, and <code>CountCandidateWork</code> supplies the operation&#39;s counting rule. A wrapper that needs the problem reads the typed <code>scope.Problem</code> in its own <code>CreateExecutor</code> and retains it in its wrapper struct or executor. Generic invocation wrappers reach no other call argument. A typed wrapper of one operation receives every argument. Keep <code>Proceed</code> without a default interface implementation, which would box the invocation on every call. <code>IOperation&lt;TSelf&gt;.SupportsCandidateWork</code> defaults to false and the invocation&#39;s <code>CountCandidateWork</code> defaults to throwing. An operation without candidate work implements neither, and one with candidate work implements both, so <code>CountCandidateWork</code> does not box where it is used. Routing a call&#39;s items is a capability of an item operation, not of its invocation: <code>IItemOperation&lt;TSelf&gt;.Route</code> returns a routed executor. No invocation method is added to executor interfaces.</p><p>A wrapping executor derives from <code>WrappingExecutor&lt;TExecutor, TWrapper&gt;</code>. A routed executor derives from <code>RoutingExecutor&lt;TExecutor&gt;</code>.</p><h2 id="§-5-immutability-and-collection-ownership" tabindex="-1">§ 5 Immutability and collection ownership <a class="header-anchor" href="#§-5-immutability-and-collection-ownership" aria-label="Permalink to “§ 5 Immutability and collection ownership”">​</a></h2><h3 id="§-5-1-treat-candidates-as-immutable-values" tabindex="-1">§ 5.1 Treat candidates as immutable values <a class="header-anchor" href="#§-5-1-treat-candidates-as-immutable-values" aria-label="Permalink to “§ 5.1 Treat candidates as immutable values”">​</a></h3><p>Any type used as <code>TCandidate</code> must behave as an immutable value.</p><ul><li>Operators must not mutate parent candidates in place.</li><li>Mutation and crossover may create new candidates but must not change existing candidates.</li><li>Search spaces, problems and algorithms should be designed around immutable candidate flow.</li></ul><h3 id="§-5-2-snapshot-retained-collections" tabindex="-1">§ 5.2 Snapshot retained collections <a class="header-anchor" href="#§-5-2-snapshot-retained-collections" aria-label="Permalink to “§ 5.2 Snapshot retained collections”">​</a></h3><p>Accept finite ordered inputs as <code>IReadOnlyList&lt;T&gt;</code>. Snapshot retained inputs with <code>ToValueArray()</code> and expose them as <code>ValueArray&lt;T&gt;</code>. Caller changes must not affect the owner.</p><p>Use <code>IReadOnlyList&lt;T&gt;</code> for transient batches and <code>IEnumerable&lt;T&gt;</code> for lazy sequences. Return mutable collections only for intentional mutation or ownership transfer.</p><h3 id="§-5-3-apply-immutability-contracts-to-retained-elements" tabindex="-1">§ 5.3 Apply immutability contracts to retained elements <a class="header-anchor" href="#§-5-3-apply-immutability-contracts-to-retained-elements" aria-label="Permalink to “§ 5.3 Apply immutability contracts to retained elements”">​</a></h3><p>Snapshots retain element references. Each element must satisfy its own mutability contract.</p><h3 id="§-5-4-choose-collection-types-by-ownership-and-meaning" tabindex="-1">§ 5.4 Choose collection types by ownership and meaning <a class="header-anchor" href="#§-5-4-choose-collection-types-by-ownership-and-meaning" aria-label="Permalink to “§ 5.4 Choose collection types by ownership and meaning”">​</a></h3><p>Choose collection types by meaning and ownership.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Situation</th><th>Type</th></tr></thead><tbody><tr><td>Collection retained by a configuration or value object</td><td><code>ValueArray&lt;T&gt;</code></td></tr><tr><td>Parameter accepting a finite ordered collection</td><td><code>IReadOnlyList&lt;T&gt;</code>, snapshotted with <code>ToValueArray()</code></td></tr><tr><td>Mathematical coordinates with broadcasting</td><td><code>RealVector</code>, <code>IntegerVector</code>, <code>BoolVector</code></td></tr><tr><td>Transient batch inside one operation, never retained</td><td><code>IReadOnlyList&lt;T&gt;</code></td></tr><tr><td>Collection held by an executor</td><td><code>ImmutableArray&lt;T&gt;</code></td></tr><tr><td>Lazy or sequence oriented API</td><td><code>IEnumerable&lt;T&gt;</code></td></tr></tbody></table></div><p>A record never implements <code>IEnumerable</code>, generic or not: a record is a value, not a sequence.</p><p>A record has value semantics, so what it holds has value semantics too, and its declared type says so. A sequence in a record&#39;s stored state or in any of its instance properties, positional, stored or computed, is typed as a concrete type with ordered structural equality: <code>ValueArray&lt;T&gt;</code>, or a domain vector such as <code>RealVector</code>, <code>IntegerVector</code>, <code>BoolVector</code>, <code>Permutation</code> or <code>ObjectiveVector</code>. It is never typed as an interface such as <code>IEnumerable&lt;double&gt;</code> or <code>IReadOnlyList&lt;T&gt;</code>, whose equality is unknown. Method parameters, method returns and static members follow the general collection guidance. A record may keep private lookup caches derived from its value members when it defines its equality over those value members only, and it does not hand those caches out mutably.</p><p>This member rule covers every public or protected record and every record whose equality, hashing or serialization is used. A private or internal record that nothing compares, hashes or serializes and that only carries values as a named tuple is exempt. Executors keep <code>ImmutableArray&lt;T&gt;</code>. Experimental code may keep arrays and mutable data in records until it is promoted (§ 9.6). The BBoB test-function data does.</p><h3 id="§-5-5-construct-value-arrays-without-accidental-nesting" tabindex="-1">§ 5.5 Construct value arrays without accidental nesting <a class="header-anchor" href="#§-5-5-construct-value-arrays-without-accidental-nesting" aria-label="Permalink to “§ 5.5 Construct value arrays without accidental nesting”">​</a></h3><p>Use <code>ValueArray.Create(a, b, c)</code> or a collection expression for elements. A single list argument becomes one element, so use <code>items.ToValueArray()</code> to snapshot a sequence. Use <code>ValueArray.FromOwnedArray(array)</code> only when the caller transfers ownership and will not mutate the array.</p><ul><li>An <code>ImmutableArray&lt;T&gt;</code> converts implicitly.</li></ul><h3 id="§-5-6-treat-the-default-value-array-as-empty" tabindex="-1">§ 5.6 Treat the default value array as empty <a class="header-anchor" href="#§-5-6-treat-the-default-value-array-as-empty" aria-label="Permalink to “§ 5.6 Treat the default value array as empty”">​</a></h3><p>The default <code>ValueArray&lt;T&gt;</code> is empty. Do not check <code>IsDefault</code> or normalize it. Use <code>Count</code>, not <code>Length</code>.</p><h3 id="§-5-7-do-not-shadow-inherited-child-collections" tabindex="-1">§ 5.7 Do not shadow inherited child collections <a class="header-anchor" href="#§-5-7-do-not-shadow-inherited-child-collections" aria-label="Permalink to “§ 5.7 Do not shadow inherited child collections”">​</a></h3><p>Do not redeclare an inherited child collection with <code>new</code>. It changes generated record equality. Give a distinct child role its own name instead.</p><h2 id="§-6-validation-and-numeric-behavior" tabindex="-1">§ 6 Validation and numeric behavior <a class="header-anchor" href="#§-6-validation-and-numeric-behavior" aria-label="Permalink to “§ 6 Validation and numeric behavior”">​</a></h2><h3 id="§-6-1-treat-nullable-annotations-as-contracts" tabindex="-1">§ 6.1 Treat nullable annotations as contracts <a class="header-anchor" href="#§-6-1-treat-nullable-annotations-as-contracts" aria-label="Permalink to “§ 6.1 Treat nullable annotations as contracts”">​</a></h3><ul><li>Do not add runtime null checks for nonnullable parameters, properties or collection elements.</li><li>Handle null when a type is explicitly nullable or code operates at an untyped external boundary.</li><li>Do not defend against deliberate contract bypasses such as <code>null!</code>, disabled nullable analysis or reflection.</li><li>Validate <code>ImmutableArray&lt;T&gt;.IsDefault</code> only when the API gives it meaning. <code>ValueArray&lt;T&gt;</code> needs no such check.</li></ul><h3 id="§-6-2-preserve-unusual-values-with-stable-semantics" tabindex="-1">§ 6.2 Preserve unusual values with stable semantics <a class="header-anchor" href="#§-6-2-preserve-unusual-values-with-stable-semantics" aria-label="Permalink to “§ 6.2 Preserve unusual values with stable semantics”">​</a></h3><p>Validate only what safety or the documented contract requires. Preserve unusual floating point values when IEEE behavior gives them stable meaning. Do not reject or clamp them by convention.</p><h3 id="§-6-3-apply-the-documented-unusual-numeric-semantics" tabindex="-1">§ 6.3 Apply the documented unusual numeric semantics <a class="header-anchor" href="#§-6-3-apply-the-documented-unusual-numeric-semantics" aria-label="Permalink to “§ 6.3 Apply the documented unusual numeric semantics”">​</a></h3><p>Apply these semantics consistently:</p><ul><li>Threshold rates below zero, negative infinity and <code>NaN</code> mean never. Rates above one and positive infinity mean always. Documented fallbacks such as <code>AtLeastOnce</code> still apply.</li><li>Empty weights mean uniform selection. Positive finite weights participate proportionally. Zero, negative values, negative infinity and <code>NaN</code> mean never.</li><li>Positive infinity overrides finite weights. Choose uniformly among multiple positive infinities. If nothing is selectable, choose uniformly among all entries.</li><li>Do not shift finite weights by their minimum. Weights express ratios, and shifting <code>[1, 3]</code> to <code>[0, 2]</code> would incorrectly make the first entry impossible.</li><li>Negative normal sigma mirrors samples around the mean. <code>NaN</code> propagates and infinities follow IEEE arithmetic.</li><li>Bounded integer conversion maps <code>NaN</code> to zero before clamping, positive infinity to the maximum and negative infinity to the minimum.</li><li>Uniform bounds with <code>high &lt;= low</code> return <code>low</code> without a random draw. Apply this per coordinate and still validate dimensions.</li></ul><h3 id="§-6-4-keep-configured-values-visible" tabindex="-1">§ 6.4 Keep configured values visible <a class="header-anchor" href="#§-6-4-keep-configured-values-visible" aria-label="Permalink to “§ 6.4 Keep configured values visible”">​</a></h3><p>Configuration properties expose supplied values, not normalized substitutes. Internal execution data may use an equivalent optimized form.</p><h3 id="§-6-5-validate-before-dangerous-or-wasteful-work" tabindex="-1">§ 6.5 Validate before dangerous or wasteful work <a class="header-anchor" href="#§-6-5-validate-before-dangerous-or-wasteful-work" aria-label="Permalink to “§ 6.5 Validate before dangerous or wasteful work”">​</a></h3><p>Validate a violation that could:</p><ul><li>Consume random draws or change state before failing.</li><li>Produce a structurally invalid candidate or configuration.</li><li>Cause unsafe indexing, invalid allocation, nontermination or corruption.</li><li>Waste substantial computation before failing.</li><li>Break an essential relationship such as compatible dimensions or matching operator and weight counts.</li></ul><h3 id="§-6-6-trust-the-algorithm-s-candidate-validity-contract" tabindex="-1">§ 6.6 Trust the algorithm&#39;s candidate validity contract <a class="header-anchor" href="#§-6-6-trust-the-algorithm-s-candidate-validity-contract" aria-label="Permalink to “§ 6.6 Trust the algorithm&#39;s candidate validity contract”">​</a></h3><p>Operators may assume that algorithm supplied candidates are valid for the algorithm&#39;s search space. Do not repeat candidate dimension, permutation content or matching dimension checks.</p><p>Direct calls with invalid candidates may fail later or produce undefined results. Continue to validate independent inputs such as broadcastable parameter dimensions.</p><h3 id="§-6-7-avoid-redundant-validation-and-normalization" tabindex="-1">§ 6.7 Avoid redundant validation and normalization <a class="header-anchor" href="#§-6-7-avoid-redundant-validation-and-normalization" aria-label="Permalink to “§ 6.7 Avoid redundant validation and normalization”">​</a></h3><p>Do not validate only to replace an immediate exception or normalize values unless normalization is the operation. Validate configuration invariants once under § 4.7. Public methods may validate inputs once, then call a trusted private implementation.</p><h3 id="§-6-8-keep-debug-and-release-behavior-equivalent" tabindex="-1">§ 6.8 Keep debug and release behavior equivalent <a class="header-anchor" href="#§-6-8-keep-debug-and-release-behavior-equivalent" aria-label="Permalink to “§ 6.8 Keep debug and release behavior equivalent”">​</a></h3><p>Debug and release builds must behave the same. Do not use debug only validation or <code>Debug.Assert</code> in library code. Enforce invariants through types or normal runtime checks.</p><h2 id="§-7-performance-and-deterministic-execution" tabindex="-1">§ 7 Performance and deterministic execution <a class="header-anchor" href="#§-7-performance-and-deterministic-execution" aria-label="Permalink to “§ 7 Performance and deterministic execution”">​</a></h2><h3 id="§-7-1-treat-hot-path-cost-as-part-of-the-design" tabindex="-1">§ 7.1 Treat hot path cost as part of the design <a class="header-anchor" href="#§-7-1-treat-hot-path-cost-as-part-of-the-design" aria-label="Permalink to “§ 7.1 Treat hot path cost as part of the design”">​</a></h3><p>Treat operator and evaluation cost as part of the design. See <a href="/contributing/design-goals.html#performance-as-a-design-constraint">Performance as a design constraint</a>.</p><ul><li>Avoid unnecessary allocation, boxing, delegate creation, context object construction and interface indirection in operator and evaluation paths.</li><li>Shared paths must remain cheap enough for lightweight operators such as <code>InversionMutator</code>.</li><li>Keep straightforward code until measurement shows a cost.</li><li>Remove an abstraction whose machinery outweighs the behavior it centralizes.</li><li>Keep results independent of workers, partitions, scheduling, concurrency limits and CPU core count. Assign random sequences by logical item or key as described in <a href="/guide/execution/randomness.html">Randomness</a>.</li></ul><h3 id="§-7-2-add-benchmark-infrastructure-only-by-accepted-decision" tabindex="-1">§ 7.2 Add benchmark infrastructure only by accepted decision <a class="header-anchor" href="#§-7-2-add-benchmark-infrastructure-only-by-accepted-decision" aria-label="Permalink to “§ 7.2 Add benchmark infrastructure only by accepted decision”">​</a></h3><p>Benchmark locally when a change presents a performance risk and report the numbers. Permanent benchmark infrastructure needs a separate accepted decision.</p><h2 id="§-8-public-api-design" tabindex="-1">§ 8 Public API design <a class="header-anchor" href="#§-8-public-api-design" aria-label="Permalink to “§ 8 Public API design”">​</a></h2><h3 id="§-8-1-design-apis-for-intended-use" tabindex="-1">§ 8.1 Design APIs for intended use <a class="header-anchor" href="#§-8-1-design-apis-for-intended-use" aria-label="Permalink to “§ 8.1 Design APIs for intended use”">​</a></h3><p>Make intended use easy and misuse difficult.</p><ul><li>Use descriptive names. Documentation does not excuse an unclear API.</li><li>Public authoring bases expose required constructors, state and modules as <code>protected</code>, not <code>private protected</code>. Otherwise do not present the type as an authoring base.</li><li>Keep related abstractions and operator roles structurally consistent.</li><li>Make defaults, side effects and potentially expensive behavior visible.</li><li>Do not give a nullable operator slot a non-null default. <code>null</code> would then mean both &quot;not supplied, use the default&quot; and &quot;deliberately absent&quot;, and a caller could no longer express the second. Either the slot stays nullable and absence is its default, or it becomes non-nullable with a no-op implementation as the default, such as an identity interceptor. A nullable <em>parameter</em> on a factory is unaffected: it means &quot;not supplied&quot; for a slot that cannot itself be null.</li><li>Return the most concrete accessible type useful to callers.</li><li>Add capability interfaces only for concrete use cases.</li><li>Do not add marker interfaces without behavior or a concrete static typing requirement.</li><li>Do not preserve unclear overloads or bases for symmetry.</li><li>Add a self type parameter only when a consumer needs the exact derived type, as fluent experiment composition does. Do not add one for symmetry.</li><li>Seal completed composition policies. Keep topology and authoring bases open.</li></ul><h3 id="§-8-2-present-the-ordinary-xml-contract-first" tabindex="-1">§ 8.2 Present the ordinary XML contract first <a class="header-anchor" href="#§-8-2-present-the-ordinary-xml-contract-first" aria-label="Permalink to “§ 8.2 Present the ordinary XML contract first”">​</a></h3><p>Put the ordinary contract and expected range in <code>&lt;summary&gt;</code>. Put unusual values and edge cases in <code>&lt;remarks&gt;</code>.</p><p>An invariant contract states something narrower, and the two must not be conflated. The range in a contract is the range in which a <strong>guarantee holds</strong>, not the range that is a good choice. A blend crossover with an alpha above one is a legitimate setting that widens the search. What it stops doing is keeping candidates inside the bounds the search space states. A mutation rate of <code>0.9</code> is unusual advice and breaks no invariant, so it stays prose and never reaches a contract. Keep judgement about good values in <code>&lt;summary&gt;</code>, and keep guarantee ranges in the contract member, so a contract does not accumulate opinions.</p><p>Where a parameter carries both, its documentation points at the member that defines the contract instead of restating the threshold. The condition is then written once, in the executable place, and prose cannot drift away from it.</p><h3 id="§-8-3-use-variance-only-when-substitution-is-meaningful" tabindex="-1">§ 8.3 Use variance only when substitution is meaningful <a class="header-anchor" href="#§-8-3-use-variance-only-when-substitution-is-meaningful" aria-label="Permalink to “§ 8.3 Use variance only when substitution is meaningful”">​</a></h3><ul><li><code>TCandidate</code> is invariant throughout the public API. It identifies the exact shared representation.</li><li>Operator executors bind the search space and problem at construction. Their interfaces omit those type parameters. General operators compose with specific problems through the authoring bases&#39; run-type checks.</li><li>A returned type parameter cannot be contravariant. This makes <code>TSearchState</code> contravariant on <code>ITerminationExecutor</code> but invariant on <code>IInterceptionExecutor</code>.</li><li>Other domain parameters use variance only for a concrete substitution requirement and use a domain specific name.</li><li>Sonar S3246 is disabled because permitted positions alone do not establish meaningful substitution.</li></ul><h3 id="§-8-4-reduce-role-arity-through-the-authoring-hierarchy" tabindex="-1">§ 8.4 Reduce role arity through the authoring hierarchy <a class="header-anchor" href="#§-8-4-reduce-role-arity-through-the-authoring-hierarchy" aria-label="Permalink to “§ 8.4 Reduce role arity through the authoring hierarchy”">​</a></h3><p>Reduced arities let authors omit operation inputs they do not use. Keep each role family consistent.</p><p>The ladder is also where the search space and problem type arguments legitimately live. They have left the role contract <code>IOperator&lt;TOperation, TCandidate&gt;</code>, but an authoring base that reads a search space or a problem still names it, deliberately, for two reasons. The base performs the type check, bridging the authored member into the candidate-only contract and reporting a mismatch when a run supplies types the operator was not written for, so the pair costs the author two type arguments and costs every consumer none. And a stateless operator&#39;s code lives on the configuration, not on an executor of its own, so it needs those values in scope where it is written. Erasing them from the authoring layer would force stateless operators to grow an executor purely to carry types, which is the boilerplate this ladder exists to remove.</p><ul><li>A reduced configuration base derives from the next fuller configuration base.</li><li>A reduced stateless base derives from the reduced configuration base. At the candidate-only arity it is its own executor, except for selection and replacement, whose base builds a private executor holding the problem to read its objective.</li></ul><h3 id="§-8-5-reduce-only-arities-that-describe-operation-inputs" tabindex="-1">§ 8.5 Reduce only arities that describe operation inputs <a class="header-anchor" href="#§-8-5-reduce-only-arities-that-describe-operation-inputs" aria-label="Permalink to “§ 8.5 Reduce only arities that describe operation inputs”">​</a></h3><p>Reduce type arguments consumed by the operator&#39;s own code. Do not reduce type arguments that describe an owned child slot.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Base</th><th style="text-align:center;">Reduced arities</th><th>Why</th></tr></thead><tbody><tr><td><code>StatelessMutator</code>, <code>Mutator</code>, <code>SingleCandidateMutator</code></td><td style="text-align:center;">Yes</td><td>Type arguments describe operation data</td></tr><tr><td><code>WrappingOperator</code>, <code>MultiOperator</code></td><td style="text-align:center;">No</td><td>Type arguments describe child slots</td></tr></tbody></table></div><p>Keep topology type arguments open so their children determine them. Reduced arities are authoring conveniences, not separate contracts: a role contract names only the candidate, and every rung of the ladder reaches it through the bridge described in § 8.4.</p><h3 id="§-8-6-provide-type-inference-helpers-when-values-supply-the-types" tabindex="-1">§ 8.6 Provide type inference helpers when values supply the types <a class="header-anchor" href="#§-8-6-provide-type-inference-helpers-when-values-supply-the-types" aria-label="Permalink to “§ 8.6 Provide type inference helpers when values supply the types”">​</a></h3><p>Do not make callers spell generic arguments available values can determine.</p><ul><li>Put public constructors on the configuration type.</li><li>Put <code>Create(...)</code>, <code>For(problem, ...)</code> and <code>For(algorithm, ...)</code> on a static companion named after the type.</li><li>Use <code>Create(...)</code> when the caller supplies the required collaborators and they determine the type arguments. Use <code>For(anchor, ...)</code> when an anchor value supplies the type arguments and may recommend omitted collaborators.</li><li>A recommendation based <code>For(...)</code> resolves explicit values first, then the documented recommendation sources in order. It throws <code>InvalidOperationException</code> during construction and names every required parameter left unresolved.</li><li>Get each required operator through <code>OperatorRecommendationResolution</code>, generic in that operator&#39;s role contract. The algorithm lists its own required parameters. Shared recommendation machinery must not group or enumerate operator roles.</li><li>A <code>Create(...)</code> or <code>For(...)</code> must be able to return a complete configuration. Accept every configurable member as a parameter, required in <code>Create</code> and optional in <code>For</code>, so a caller is never left finishing a partly configured result. <code>with</code> changes a configuration that already exists. It is not the way to complete one the factory could not build.</li><li>Anchor a <code>For(...)</code> that also takes optional operators on an invariant parameter type. A covariant anchor such as <code>IProblem&lt;TCandidate, out TSearchSpace&gt;</code> contributes only a lower bound, so an operator declared at a reduced arity widens the inferred search space and fails against constraints the caller never named. An invariant anchor contributes an exact bound, fixing the type from the anchor alone.</li><li>Treat a <code>For(...)</code> argument as a type witness unless the contract says it is retained.</li><li>Add a fluent extension only when its receiver becomes part of the configuration.</li><li>Put fluent methods in <code>&lt;Type&gt;Extensions</code>. A concern specific helper such as <code>AppliedAtRate</code> may use its own companion.</li><li>Keep direct construction when no value can supply the types.</li><li>Prove intended inference with API usage specs. Use architecture tests or analyzers only where each fits under § 10.1.</li></ul><h3 id="§-8-7-keep-operator-parameter-groups-in-a-common-order" tabindex="-1">§ 8.7 Keep operator parameter groups in a common order <a class="header-anchor" href="#§-8-7-keep-operator-parameter-groups-in-a-common-order" aria-label="Permalink to “§ 8.7 Keep operator parameter groups in a common order”">​</a></h3><p>Order an operation executor&#39;s parameters as primary inputs followed by the RNG, including termination and external operations. Bind the problem during construction through the typed scope. The executor retains what it needs. Stateless author overrides retain primary inputs, RNG, search space and problem, omitting context groups at reduced authoring arities. Lower level inputs that replace a search space occupy its position.</p><p>Generic types and methods that name an operation put it first: <code>TOperation, TCandidate, TSearchSpace, TProblem, TSearchState, ...</code>, omitting parameters that do not apply. Keep managed <code>TState</code> last. Apply this order across operator contracts, operations, authoring bases, compositions, wrappers and resolution methods. For example, use <code>IOperator&lt;Mutation, RealVector&gt;</code>. Families without an operation parameter retain their established order.</p><h3 id="§-8-8-expose-direct-static-implementations-when-the-operation-needs-one" tabindex="-1">§ 8.8 Expose direct static implementations when the operation needs one <a class="header-anchor" href="#§-8-8-expose-direct-static-implementations-when-the-operation-needs-one" aria-label="Permalink to “§ 8.8 Expose direct static implementations when the operation needs one”">​</a></h3><p>Expose a direct static implementation when the candidate or genotype does not already own the operation.</p><ul><li>Do not add a static method that only forwards to the candidate or genotype.</li><li>Name the static method for the operation, such as <code>Create</code>, <code>Mutate</code>, <code>Cross</code>, <code>Select</code> or <code>Evaluate</code>. Let the executor method delegate to it.</li><li>Provide one core overload that accepts the direct inputs needed by the operation.</li><li>Use search space overloads as thin adapters unless the search space is the true dependency.</li><li>Order adapters before the core overload and delegate inward.</li><li>Validate at the public boundary. Use a trusted private implementation to avoid repeated checks.</li></ul><h3 id="§-8-9-group-extensions-by-user-facing-concern" tabindex="-1">§ 8.9 Group extensions by user facing concern <a class="header-anchor" href="#§-8-9-group-extensions-by-user-facing-concern" aria-label="Permalink to “§ 8.9 Group extensions by user facing concern”">​</a></h3><p>Group extensions by user concern, not target type alone. Give observation, counting, duration, budget, factory and conversion helpers separate classes. Use concern names, such as <code>OperatorDurationExtensions</code>.</p><p>Write extensions as extension blocks. Keep a classic extension method only where a block cannot express it or would reorder its explicit type arguments, such as an operation that must stay first under § 8.7. Put an extension class in the file of the type it extends unless it is large enough to warrant its own file.</p><p>Folders may group implementations without forcing a public namespace. Keep implementation wrappers private or internal unless callers need their concrete type.</p><h3 id="§-8-10-build-random-apis-in-layers" tabindex="-1">§ 8.10 Build random APIs in layers <a class="header-anchor" href="#§-8-10-build-random-apis-in-layers" aria-label="Permalink to “§ 8.10 Build random APIs in layers”">​</a></h3><p>Build random APIs from one source of base random values.</p><ol><li>RNG methods provide base random values.</li><li>Scalar helpers build on them.</li><li>Typed output helpers build domain values from scalar helpers.</li><li>Search space helpers forward configuration to typed output helpers.</li><li>Creator operators add only operator level guarantees.</li><li>Type factory aliases forward to the RNG helpers.</li></ol><p>Use concept first scalar names such as <code>NextDouble</code> and target first output names such as <code>NextRealVectorUniform</code>. Do not add a competing distribution layer for the same sampling behavior.</p><h3 id="§-8-11-let-an-api-surface-scale-per-role-never-over-hidden-axes" tabindex="-1">§ 8.11 Let an API surface scale per role, never over hidden axes <a class="header-anchor" href="#§-8-11-let-an-api-surface-scale-per-role-never-over-hidden-axes" aria-label="Permalink to “§ 8.11 Let an API surface scale per role, never over hidden axes”">​</a></h3><p>Each operation supplies one invocation over its named method. General wrappers reuse <code>TOperation.Wrap</code> and <code>IInvocationWrapper</code>. Do not add another matrix per wrapper or run signature. Candidate-work semantics are supplied by the invocation (§ 4.19) and evaluated only by wrappers needing that metric. Do not add operation or invocation members for retry, timing, counting or other individual behaviors. Per-item choice uses an item operation&#39;s <code>Route</code>, and a per-invocation choice uses the invocation&#39;s <code>Random</code> and <code>Proceed</code>.</p><p>Duplicating a member once per operator role is acceptable. Adding a role is a deliberate act, its author writes the role&#39;s members once from an obvious template, and no existing role is disturbed. The resolve family (<code>Resolve</code>, <code>ResolveOptional</code>, <code>TryResolve</code>), the observation sources beside each operation and named configuration wrappers all have this shape.</p><p>What is not acceptable is a surface that multiplies over an axis the role&#39;s author does not know exists, so that adding one role silently obliges members for every value of some other dimension. Before adding a per-role member, name the axes it varies over and check that a role author can enumerate all of them.</p><p>Two receivers for the same operation are not a second axis when one is defined in terms of the other. <code>scope.Resolve&lt;TCandidate, TSearchSpace, TProblem&gt;(config)</code> is canonical — the scope is generic-less and cannot infer the triple. <code>typed.Resolve(config)</code> goes through a <code>ResolutionScope</code> that already knows the triple, infers everything and relays to the canonical form. One mechanism, two spellings. Keep both.</p><p>Whatever the declaration count, the call site stays minimal: <code>typed.Resolve(config)</code> or <code>typed.TryResolve(config, out var executor, out var reason)</code>, with nothing the caller is forced to supply to make inference work. An overload that exists so a type argument can be inferred is justified. One that exists only so a call site reads differently needs a separate argument.</p><h3 id="§-8-12-name-a-method-for-what-it-returns-not-for-what-it-looks-like" tabindex="-1">§ 8.12 Name a method for what it returns, not for what it looks like <a class="header-anchor" href="#§-8-12-name-a-method-for-what-it-returns-not-for-what-it-looks-like" aria-label="Permalink to “§ 8.12 Name a method for what it returns, not for what it looks like”">​</a></h3><p><code>With*</code> is the record convention: same type, changed slot, nothing mutated. Reserve it for exactly that.</p><p>A method that returns a <strong>different type wrapping the receiver</strong> is named as a past participle describing the result, because an adjective cannot be misread as a command to modify the receiver: <code>algorithm.TerminatedBy(terminator)</code>, <code>evaluator.Cached(keySelector)</code>, <code>refiner.CheckedForImprovement()</code>, <code>mutator.AppliedAtRate(0.3)</code>, <code>algorithm.LimitedToCandidates(evaluator, 100_000)</code>. <code>ga.TerminatedBy(t)</code> is not a genetic algorithm any more, and the name should not suggest otherwise.</p><p>A method that <strong>mutates the receiver</strong> is named with an imperative verb, such as <code>scope.Share(configuration)</code>, and never with <code>With*</code>, even when it returns the receiver for chaining. A fluent chain is not evidence that a value is being built, so the name has to carry that distinction on its own.</p><p>This was applied across the library after <code>With*</code> was found covering three different semantics at once, one of which genuinely modified its receiver while reading exactly like the other two.</p><p>A configuration that is not yet a run names its execution methods with <code>Run</code>: algorithms and experiments offer <code>RunStreaming</code>, <code>RunToCompletion</code> and <code>RunToCompletionAsync</code>, and experiments also offer <code>RunTrials</code>. Each is exactly <code>CreateRun(…)</code> followed by the run&#39;s method. A run uses the bare verb: <code>Stream</code>, <code>Complete</code>, <code>CompleteAsync</code>, and <code>StartTrials</code>, which returns before the trials finish.</p><h3 id="§-8-13-name-a-contract-member-for-the-question-it-answers" tabindex="-1">§ 8.13 Name a contract member for the question it answers <a class="header-anchor" href="#§-8-13-name-a-contract-member-for-the-question-it-answers" aria-label="Permalink to “§ 8.13 Name a contract member for the question it answers”">​</a></h3><p>Prefer a member name that reads as the predicate at the call site: <code>invariant.Holds(candidate)</code>, <code>exactCount.Implies(minimumCount)</code>, <code>contract.Ensures(invariant)</code>. Avoid names that state a mechanism (<code>IsSatisfiedBy</code>) or a term of art the reader must look up (<code>Entails</code>) where a plain word carries the same meaning.</p><p>Name an interface for what it is about, not only for its role in a system: <code>ICandidateInvariant&lt;TCandidate&gt;</code> says which thing the invariant constrains, and <code>IOperatorContract&lt;TCandidate&gt;</code> says whose contract it is. Verify the verb covers every implementer: <code>Ensures</code> includes creators that establish an invariant as well as operators that preserve it.</p><h3 id="§-8-14-say-item-for-a-split-call-and-candidate-for-the-candidates" tabindex="-1">§ 8.14 Say item for a split call and candidate for the candidates <a class="header-anchor" href="#§-8-14-say-item-for-a-split-call-and-candidate-for-the-candidates" aria-label="Permalink to “§ 8.14 Say item for a split call and candidate for the candidates”">​</a></h3><p>A name says item when it belongs to splitting or routing a call, which any item operation can use, such as <code>IItemOperation&lt;TSelf&gt;</code> and <code>ChoosePerItem</code>. A name says candidate when it is about candidates themselves: an operation&#39;s candidate inputs and outputs (<code>SingleCandidateMutator</code>, <code>MutateCandidate</code>), candidate work (<code>SupportsCandidateWork</code>, <code>CountCandidateWork</code>, <code>CountingCandidates</code>, <code>LimitedToCandidates</code>). Rate helpers such as <code>AppliedAtRate</code> return <code>ChoosePerItem</code> and describe each operation&#39;s own unit in their documentation, such as each parent, parent group or candidate.</p><p>An item does not always yield a candidate: evaluation yields an objective vector for each candidate, and a crossover item is a group of parents. That is why a name that works for every item operation says item.</p><h2 id="§-9-documentation-and-source-organization" tabindex="-1">§ 9 Documentation and source organization <a class="header-anchor" href="#§-9-documentation-and-source-organization" aria-label="Permalink to “§ 9 Documentation and source organization”">​</a></h2><h3 id="§-9-1-document-nonobvious-public-contracts" tabindex="-1">§ 9.1 Document nonobvious public contracts <a class="header-anchor" href="#§-9-1-document-nonobvious-public-contracts" aria-label="Permalink to “§ 9.1 Document nonobvious public contracts”">​</a></h3><p>Add XML documentation only for a nonobvious contract, invariant, lifecycle, failure, algorithm detail or usage constraint. Prefer a clear name and signature.</p><ul><li>Do not add summaries that only repeat a type, member or parameter name.</li><li>Put design rationale and examples in <code>docs</code>.</li><li>Do not add XML documentation to tests.</li></ul><h3 id="§-9-2-keep-policy-and-public-documentation-in-their-assigned-documents" tabindex="-1">§ 9.2 Keep policy and public documentation in their assigned documents <a class="header-anchor" href="#§-9-2-keep-policy-and-public-documentation-in-their-assigned-documents" aria-label="Permalink to “§ 9.2 Keep policy and public documentation in their assigned documents”">​</a></h3><ul><li>Use glossary terms instead of ad hoc alternatives.</li><li>Keep user facing namespaces focused on concepts. Folders may be more detailed.</li><li>Do not assume that one folder must map to one namespace.</li><li>Keep public behavioral explanations in topic documentation.</li><li>Keep contributor implementation rules in this document.</li></ul><h3 id="§-9-3-name-types-for-what-binds-them-place-them-by-what-they-are" tabindex="-1">§ 9.3 Name types for what binds them, place them by what they are <a class="header-anchor" href="#§-9-3-name-types-for-what-binds-them-place-them-by-what-they-are" aria-label="Permalink to “§ 9.3 Name types for what binds them, place them by what they are”">​</a></h3><p>Name a type for the narrowest domain or representation that binds it. Use genotype names for types that work with any problem over that genotype. Use domain names for types that require one problem.</p><p>Place a type with the concept it implements, not with the representation that binds it. A problem, including an authoring base bound to one representation such as <code>RealVectorProblem</code>, belongs in <code>Problems</code>. An operator authoring base belongs in its role namespace. An encoding holds its representation&#39;s candidate types, search spaces and the operators that work with any problem over that representation. Put an operator that requires one problem beside that problem, as <code>NumericParameterFittingRefiner</code> sits in <code>Problems.MachineLearning</code>.</p><p>Name a role-specific configuration interface for its role, without a <code>Node</code> suffix. <code>IOperator&lt;Mutation, TCandidate&gt;</code>, <code>IAlgorithm&lt;TCandidate&gt;</code> and <code>IClock</code> are configuration nodes by deriving from <code>IConfigurationNode</code>, and the <code>IConfigurationNode</code> interfaces are the only configuration interfaces named for the graph concept.</p><h3 id="§-9-4-allow-authoring-dependencies-required-by-construction" tabindex="-1">§ 9.4 Allow authoring dependencies required by construction <a class="header-anchor" href="#§-9-4-allow-authoring-dependencies-required-by-construction" aria-label="Permalink to “§ 9.4 Allow authoring dependencies required by construction”">​</a></h3><p>An authoring type may depend on a search space even when the candidate representation does not. Construction may require this dependency. Do not weaken the authoring API to remove it.</p><p>For example, <code>ExpressionDraft</code> takes an <code>ExpressionTreeSearchSpace</code> to resolve symbols while building, even though <code>ExpressionTree</code> itself does not depend on a search space.</p><h3 id="§-9-5-match-namespaces-and-folders-by-audience" tabindex="-1">§ 9.5 Match namespaces and folders by audience <a class="header-anchor" href="#§-9-5-match-namespaces-and-folders-by-audience" aria-label="Permalink to “§ 9.5 Match namespaces and folders by audience”">​</a></h3><ul><li>Put user facing types in concept namespaces.</li><li>Use detailed namespaces only for contracts, bases and machinery that authors reach for rather than users.</li><li>Give a concept one namespace. Do not split it into small public namespaces that a user has to import together.</li><li>A source subfolder adds a namespace segment only when it changes the audience. Folders may organize implementation categories without adding a namespace segment.</li><li>Every namespace segment must map to its corresponding source folder. Additional grouping folders belong beneath that namespace folder: types in <code>HEAL.HeuristicLib.Execution</code> may live in <code>Execution/Runs</code> or <code>Execution/Concurrency</code> without adding a namespace segment.</li><li>Use architecture tests for reviewed concept boundaries. Do not enforce a mechanical namespace to path equation across the project.</li><li>Keep project roots free of source files. Put every type in the folder for its owning concept even when its namespace is intentionally broader than that folder.</li></ul><h3 id="§-9-6-keep-package-placement-deliberate" tabindex="-1">§ 9.6 Keep package placement deliberate <a class="header-anchor" href="#§-9-6-keep-package-placement-deliberate" aria-label="Permalink to “§ 9.6 Keep package placement deliberate”">​</a></h3><p>A component belongs in the main package when its responsibility is part of the standard HeuristicLib toolkit, its current contract is coherent and complete, its important behavior is tested and its dependencies are suitable for ordinary users.</p><p>A component belongs in Experimental when it has a real use case but its public model or semantics remain unsettled, it is a research workflow with limited validation, it is retained legacy code or it depends on another experimental component.</p><p>Do not move empty implementations, inaccessible results or known unbounded defects to Experimental. Remove them, make them internal or complete them first.</p><p>Promote a feature from Experimental only when its responsibility belongs in the standard toolkit, its central API has no expected replacement, its ownership rules match this guide, its advertised behavior is complete, its normal setup has an API usage spec and its important failure behavior has unit tests. Promotion must not force unrelated experimental concepts or unsuitable dependencies into the main package.</p><p>The main package must never reference Experimental. Experimental may reference the main package.</p><h3 id="§-9-7-keep-xml-documentation-verifiable-by-the-build" tabindex="-1">§ 9.7 Keep XML documentation verifiable by the build <a class="header-anchor" href="#§-9-7-keep-xml-documentation-verifiable-by-the-build" aria-label="Permalink to “§ 9.7 Keep XML documentation verifiable by the build”">​</a></h3><p><code>Directory.Build.props</code> sets <code>GenerateDocumentationFile</code>, so the compiler parses every <code>///</code> block and resolves every <code>cref</code>. The generated XML file ships in the NuGet package for consumer IntelliSense, but the checks are the reason the flag is on.</p><p>A documentation comment that states something false about the code is an error. A comment that is merely missing is not.</p><ul><li>Errors: CS1570, CS1571, CS1572, CS1574, CS1580, CS1584, CS1587, CS1710 and CS1711. These report badly formed XML, an unresolvable or malformed <code>cref</code>, a <code>param</code> or <code>typeparam</code> tag naming something that does not exist or naming it twice, and a comment placed on an element that cannot carry one.</li><li>Warnings: CS1573 and CS1712, which report a tag that is absent rather than one that is wrong.</li><li>CS1591 is suppressed. It reports documentation coverage, which § 9.1 deliberately does not require.</li><li>Add a diagnostic to the error list only when it reports a comment that contradicts the code.</li></ul><p>An incremental build does not re-emit these diagnostics, so verification needs a clean build.</p><h3 id="§-9-8-use-consistent-markdown-emphasis" tabindex="-1">§ 9.8 Use consistent Markdown emphasis <a class="header-anchor" href="#§-9-8-use-consistent-markdown-emphasis" aria-label="Permalink to “§ 9.8 Use consistent Markdown emphasis”">​</a></h3><p>Use <code>_italic text_</code> for emphasis and <code>**bold text**</code> for strong emphasis, following the repository&#39;s Prettier output. Code spans, fenced code and literal underscores retain their original meaning. Let Prettier choose an alternative delimiter only when necessary to preserve nested or intraword emphasis.</p><h3 id="§-9-9-keep-an-interface-beside-its-primary-implementation" tabindex="-1">§ 9.9 Keep an interface beside its primary implementation <a class="header-anchor" href="#§-9-9-keep-an-interface-beside-its-primary-implementation" aria-label="Permalink to “§ 9.9 Keep an interface beside its primary implementation”">​</a></h3><p>An interface with one primary implementation shares a file with that implementation, and the file is named after the implementation, as <code>IQuadraticAssignmentProblemData</code> sits in <code>QuadraticAssignmentProblemData.cs</code>. An interface with several implementations of equal standing keeps a file of its own.</p><p>Question an interface that has a single implementation and will likely keep it. A concrete need justifies it, such as an external implementation, a test double or a variance requirement. Without one, the class alone is the contract. This is a reason to reconsider new interfaces, not to remove published ones: a public interface ships in the package, and removing it needs its own decision.</p><h2 id="§-10-enforcement-and-implementation-style" tabindex="-1">§ 10 Enforcement and implementation style <a class="header-anchor" href="#§-10-enforcement-and-implementation-style" aria-label="Permalink to “§ 10 Enforcement and implementation style”">​</a></h2><h3 id="§-10-1-match-each-rule-to-its-enforcement-mechanism" tabindex="-1">§ 10.1 Match each rule to its enforcement mechanism <a class="header-anchor" href="#§-10-1-match-each-rule-to-its-enforcement-mechanism" aria-label="Permalink to “§ 10.1 Match each rule to its enforcement mechanism”">​</a></h3><ul><li>Use the type system and API shape for invariants that can be made unrepresentable.</li><li>Use unit tests for local behavior and domain invariants.</li><li>Use API usage specs for intended public syntax and type inference.</li><li>Use Roslyn analyzers and code fixes for recognizable source mistakes.</li><li>Use architecture tests for assembly wide relationships and cross cutting public type rules.</li><li>Use documentation for rules that require judgment.</li></ul><h3 id="§-10-2-follow-repository-validation-and-test-placement-guidance" tabindex="-1">§ 10.2 Follow repository validation and test placement guidance <a class="header-anchor" href="#§-10-2-follow-repository-validation-and-test-placement-guidance" aria-label="Permalink to “§ 10.2 Follow repository validation and test placement guidance”">​</a></h3><p>Follow <code>test/README.md</code> for test placement and validation order, and <code>AGENTS.md</code> for validation commands.</p><h3 id="§-10-3-use-block-bodies-for-methods" tabindex="-1">§ 10.3 Use block bodies for methods <a class="header-anchor" href="#§-10-3-use-block-bodies-for-methods" aria-label="Permalink to “§ 10.3 Use block bodies for methods”">​</a></h3><p>Give methods a block body. Use an expression body only for a trivial member that fits on one line, such as a forwarding call or a property getter. A body that spans several lines is a block, even when it only forwards. IDE0021 enforces block bodies for constructors. Review other methods manually.</p><h3 id="§-10-4-keep-diagnostic-exceptions-narrow" tabindex="-1">§ 10.4 Keep diagnostic exceptions narrow <a class="header-anchor" href="#§-10-4-keep-diagnostic-exceptions-narrow" aria-label="Permalink to “§ 10.4 Keep diagnostic exceptions narrow”">​</a></h3><p>Fix diagnostics instead of suppressing them. For an intentional local exception with a standard ID, use a narrow <code>#pragma warning disable</code> and <code>#pragma warning restore</code> pair.</p><p>Reserve <code>.editorconfig</code> severity changes for repository wide policy. Keep vendor specific suppressions in personal IDE settings.</p>`,250)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};